// Filters and keyset pagination of the audit log (MOD-03-T10). Pure functions,
// unit-tested in audit.query.spec.ts.
//
// Ordering: newest first by `id`. The primary key is a UUIDv7 generated by
// PostgreSQL at insert time — time-ordered with a unique tie-breaker — so the
// cursor is exact. `created_at` could not serve as the cursor: it has
// microsecond precision that an ISO 8601 string cannot carry, so a timestamp
// cursor skipped every event sharing the millisecond of the last item
// (KI-042). `before` stays a plain time filter on `created_at`.
import type { Prisma } from '../generated/prisma/client.js';
import { escapeLikePattern } from '../users/users.validation.js';

export const AUDIT_PAGE_DEFAULT = 50;
export const AUDIT_PAGE_MAX = 200;

/** Event names are dotted lower-case segments (`users.status.changed`); the filter is a prefix of one, 1–64 characters. */
export const AUDIT_ACTION_PATTERN = /^[a-z][a-z0-9_.]{0,63}$/;
/** Entity types are table names (`users`, `roles`). */
export const ENTITY_TYPE_PATTERN = /^[a-z][a-z0-9_]{0,63}$/;
/** Entity ids are text (`audit_logs.entity_id`); UUIDs today, catalog keys possible. */
export const ENTITY_ID_MAX_LENGTH = 128;
export const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export interface AuditListFilters {
  /** Prefix of the event name, matched literally (`_` is not a wildcard). */
  action?: string;
  actorUserId?: string;
  entityType?: string;
  entityId?: string;
  /** ISO 8601: events created strictly before this instant. */
  before?: string;
  /** `nextCursor` of the previous page = id of its last item; older events only. */
  cursor?: string;
}

/** Translates the validated query into a Prisma filter; every criterion is ANDed. */
export function buildAuditWhere(filters: AuditListFilters): Prisma.AuditLogWhereInput {
  const where: Prisma.AuditLogWhereInput = {};
  if (filters.action) where.action = { startsWith: escapeLikePattern(filters.action) };
  if (filters.actorUserId) where.actorUserId = filters.actorUserId;
  if (filters.entityType) where.entityType = filters.entityType;
  if (filters.entityId) where.entityId = filters.entityId;
  if (filters.before) where.createdAt = { lt: new Date(filters.before) };
  if (filters.cursor) where.id = { lt: filters.cursor };
  return where;
}

/**
 * Cuts the `limit + 1` rows fetched for a page: the extra row only tells that
 * an older page exists, so `nextCursor` is never handed out for an empty page.
 */
export function pageOf<T extends { id: string }>(rows: readonly T[], limit: number): { items: T[]; nextCursor: string | null } {
  const items = rows.slice(0, limit);
  const last = items.at(-1);
  return { items, nextCursor: rows.length > limit && last ? last.id : null };
}
